rx-basics-001.example:
```js
const text = 'Order #42 shipped, order #7 pending';

// 1) test — does the text contain a number?
console.log(/\d+/.test(text)); // true

// 2) find all numbers
console.log(text.match(/\d+/g)); // ['42', '7']

// 3) replace every '#<n>' with 'ID <n>'
console.log(text.replace(/#(\d+)/g, 'ID $1'));
// 'Order ID 42 shipped, order ID 7 pending'
```

rx-basics-002.example:
```js
// Literal — fixed pattern
const re1 = /\d{3}/;
console.log(re1.test('abc123')); // true

// Constructor — built from a variable
const word = 'cat';
const re2 = new RegExp(word, 'i');
console.log(re2.test('A CAT')); // true

// Note the doubled backslash in a constructor string:
const re3 = new RegExp('\\d{3}'); // same as /\d{3}/
console.log(re3.test('x999')); // true
```

rx-basics-mcq-001.example:
```js
const word = 'cat';

// Correct: build a case-insensitive regex from the variable
const good = new RegExp(word, 'i');
console.log(good.test('My CAT')); // true

// Wrong: the literal matches the text 'word', not the variable
const bad = /word/i;
console.log(bad.test('My CAT')); // false
console.log(bad.test('a WORD')); // true (matched the literal letters)
```

rx-basics-003.example:
```js
const s = 'a-b-c';

// Without g: first match only
console.log(s.match(/-/));     // ['-', index: 1, ...]
console.log(s.replace(/-/, '+')); // 'a+b-c'

// With g: all matches
console.log(s.match(/-/g));     // ['-', '-']
console.log(s.replace(/-/g, '+')); // 'a+b+c'
```

rx-basics-mcq-002.example:
```js
const text = 'first\nsecond\nthird';

// Without m: ^ only matches the very start of the string
console.log(text.match(/^\w+/g)); // ['first']

// With m: ^ matches the start of each line
console.log(text.match(/^\w+/gm)); // ['first', 'second', 'third']
```

rx-basics-mr-001.example:
```js
const re = /abc/gim;
console.log(re.flags);     // 'gim'
console.log(re.global);    // true
console.log(re.multiline); // true

// Invalid flag -> SyntaxError at creation time
try {
  new RegExp('abc', 'x'); // not a JS flag
} catch (e) {
  console.log(e.name); // 'SyntaxError'
}
```

rx-char-002.example:
```js
console.log('hello_world 99!'.match(/\w+/g));
// ['hello_world', '99'] — note underscore kept, space & ! split

// \W: the non-word characters
console.log('a-b c'.match(/\W/g)); // ['-', ' ']

// Accents are NOT \w by default
console.log('café'.match(/\w+/g)); // ['caf'] — é dropped
```

rx-char-003.example:
```js
const messy = 'one   two\tthree\nfour';

// Split on any run of whitespace
console.log(messy.split(/\s+/)); // ['one','two','three','four']

// Collapse all whitespace to single spaces
console.log(messy.replace(/\s+/g, ' ')); // 'one two three four'

// \S — keep only non-whitespace
console.log('a b c'.match(/\S/g)); // ['a','b','c']
```

rx-char-004.example:
```js
// Dot = any char (so this 'works' but is too loose)
console.log(/3.14/.test('3x14')); // true (!) the dot matched 'x'

// Escaped dot = literal period
console.log(/3\.14/.test('3x14')); // false
console.log(/3\.14/.test('3.14')); // true

// dotAll: let . cross newlines
console.log(/a.b/.test('a\nb'));  // false
console.log(/a.b/s.test('a\nb')); // true
```

rx-char-mcq-001.example:
```js
// Any single non-vowel
console.log('hello'.match(/[^aeiou]/g)); // ['h','l','l']

// Negated class with a quantifier: runs of non-digits
console.log('a12b3'.match(/[^0-9]+/g)); // ['a','b']

// Compare: ^ OUTSIDE brackets is the start anchor
console.log(/^a/.test('apple')); // true (starts with a)
```

rx-char-mcq-002.example:
```js
// Lowercase letters only
console.log('aB3z'.match(/[a-z]/g)); // ['a','z']

// Combined ranges = alphanumeric
console.log('aB3 _!'.match(/[A-Za-z0-9]/g)); // ['a','B','3']

// Literal hyphen (placed last)
console.log('a-b'.match(/[a-z-]/g)); // ['a','-','b']
```

rx-anchor-002.example:
```js
console.log(/\bcat\b/.test('a cat sat')); // true (standalone word)
console.log(/\bcat\b/.test('category')); // false (inside a word)

// Whole-word replace
console.log('cat category cats'.replace(/\bcat\b/g, 'DOG'));
// 'DOG category cats'

// \B — the non-boundary inverse
console.log(/\Bcat\B/.test('scatter')); // true
```

rx-quant-002.example:
```js
const log = 'start[INFO]middle[WARN]end';

// Greedy: spans from first [ to last ]
console.log(log.match(/\[.+\]/)[0]); // '[INFO]middle[WARN]'

// Lazy: each shortest [...] chunk
console.log(log.match(/\[.+?\]/g)); // ['[INFO]', '[WARN]']
```

rx-group-001.example:
```js
// Capture date parts
const m = '2026-06-25'.match(/(\d{4})-(\d{2})-(\d{2})/);
console.log(m[0]); // '2026-06-25' (whole match)
console.log(m[1]); // '2026' (group 1)
console.log(m[2]); // '06'   (group 2)

// Grouping for a quantifier
console.log(/^(ab)+$/.test('ababab')); // true
```

rx-group-mcq-001.example:
```js
// Unscoped | spans the whole pattern (surprising!)
console.log(/^cat|dog$/.test('cathouse'));  // true  (starts 'cat')
console.log(/^cat|dog$/.test('hotdog'));     // true  (ends 'dog')

// Scoped: exactly 'cat' or exactly 'dog'
const re = /^(cat|dog)$/;
console.log(re.test('cat'));      // true
console.log(re.test('cathouse')); // false
```

rx-group-002.example:
```js
// Non-capturing prefix, capturing the part we want
const m = 'https://example.com'.match(/(?:https?:\/\/)?(\w+\.\w+)/);
console.log(m[1]); // 'example.com' — group 1 is the domain, not the scheme

// Compare capture numbering:
console.log('abab'.match(/(?:ab)(ab)/)[1]); // 'ab' (only one capture)
```

rx-group-003.example:
```js
const m = '2026-06'.match(/(?<year>\d{4})-(?<month>\d{2})/);
console.log(m.groups.year);  // '2026'
console.log(m.groups.month); // '06'

// Use named groups in a replacement
const out = '2026-06-25'.replace(
  /(?<y>\d{4})-(?<m>\d{2})-(?<d>\d{2})/,
  '$<d>/$<m>/$<y>'
);
console.log(out); // '25/06/2026'
```

rx-escape-001.example:
```js
// IP-like pattern: real dots must be escaped
const re = /^\d+\.\d+\.\d+\.\d+$/;
console.log(re.test('192.168.0.1')); // true
console.log(re.test('192x168x0x1')); // false (no literal dots)

// Escape user input before using it as a pattern
const userText = 'a.b';
const escaped = userText.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
console.log(new RegExp(escaped).test('a.b')); // true
console.log(new RegExp(escaped).test('axb')); // false
```

rx-method-match-001.example:
```js
const m = 'a1b2'.match(/\d/);
console.log(m[0]);     // '1' (first match)
console.log(m.index);  // 1   (position)
console.log(m.input);  // 'a1b2'

// Capture groups appear at [1], [2], ...
const d = '2026-06'.match(/(\d{4})-(\d{2})/);
console.log(d[1], d[2]); // '2026' '06'
```

rx-method-match-002.example:
```js
const m = 'abc'.match(/\d/);
console.log(m); // null

// Unsafe — would throw:
// console.log(m.length);

// Safe patterns:
console.log(m?.[0] ?? 'no match'); // 'no match'
if (m) console.log(m[0]); else console.log('none'); // 'none'

// matchAll + spread is always an array (never null)
console.log([...'abc'.matchAll(/\d/g)].length); // 0
```

rx-method-matchall-001.example:
```js
const s = 'a1 b2 c3';
const matches = [...s.matchAll(/([a-z])(\d)/g)];

for (const m of matches) {
  console.log(m[0], 'letter=' + m[1], 'digit=' + m[2], '@' + m.index);
}
// a1 letter=a digit=1 @0
// b2 letter=b digit=2 @3
// c3 letter=c digit=3 @6

// Missing g throws:
try { 'a1'.matchAll(/\d/); } catch (e) { console.log(e.name); } // 'TypeError'
```

rx-method-matchall-mcq-001.example:
```js
const pairs = 'x=1;y=2;z=3';

// match + g: groups are lost
console.log(pairs.match(/(\w)=(\d)/g)); // ['x=1','y=2','z=3'] only

// matchAll: keep the key and value of each pair
const obj = {};
for (const m of pairs.matchAll(/(\w)=(\d)/g)) {
  obj[m[1]] = Number(m[2]);
}
console.log(obj); // { x: 1, y: 2, z: 3 }
```

rx-method-replace-001.example:
```js
console.log('a-b-c'.replace(/-/, '+'));  // 'a+b-c' (first only)
console.log('a-b-c'.replace(/-/g, '+')); // 'a+b+c' (all)

// String first arg also replaces only the first:
console.log('a-b-c'.replace('-', '+')); // 'a+b-c'

// Original is unchanged (immutable)
const s = 'a-b';
s.replace(/-/, '+');
console.log(s); // 'a-b'
```

rx-method-replace-mcq-001.example:
```js
// Swap two words using captured groups
console.log('John Smith'.replace(/(\w+) (\w+)/, '$2 $1'));
// 'Smith John'

// $& = whole match; wrap every number in brackets
console.log('a1 b22'.replace(/\d+/g, '[$&]')); // 'a[1] b[22]'

// $$ for a literal dollar sign
console.log('5'.replace(/\d+/, '$$$&')); // '$5'
```

rx-method-replace-002.example:
```js
// Double every number
console.log('a1 b2 c3'.replace(/\d+/g, (m) => Number(m) * 2));
// 'a2 b4 c6'

// Use capture groups in the callback: Title Case
console.log('hello world'.replace(/(\w)(\w*)/g,
  (whole, first, rest) => first.toUpperCase() + rest));
// 'Hello World'
```

rx-method-replaceall-001.example:
```js
// Plain string: replaces every occurrence, no regex
console.log('a,b,c'.replaceAll(',', ';')); // 'a;b;c'

// Regex MUST be global
console.log('a-b-c'.replaceAll(/-/g, '+')); // 'a+b+c'

// Non-global regex -> TypeError
try { 'a-b'.replaceAll(/-/, '+'); } catch (e) { console.log(e.name); }
// 'TypeError'
```

rx-method-search-001.example:
```js
console.log('abc4'.search(/\d/)); // 3 (first digit at index 3)
console.log('abc'.search(/\d/));  // -1 (no match)

// As a contains-check
const hasDigit = (s) => s.search(/\d/) !== -1;
console.log(hasDigit('hi5')); // true

// g flag is ignored — still the first position
console.log('a1b2'.search(/\d/g)); // 1
```

rx-method-exec-001.example:
```js
const re = /(\w)(\d)/g;
const s = 'a1 b2 c3';
let m;
while ((m = re.exec(s)) !== null) {
  console.log(`match ${m[0]} at ${m.index}, lastIndex now ${re.lastIndex}`);
}
// match a1 at 0, lastIndex now 2
// match b2 at 3, lastIndex now 5
// match c3 at 6, lastIndex now 8
```

rx-method-mr-001.example:
```js
const s = 'abc';

console.log(/\d/.test(s));            // false — safe
console.log(s.search(/\d/) !== -1);   // false — safe

// Unsafe: match() is null here, so .length throws
try { s.match(/\d/).length > 0; } catch (e) { console.log(e.name); }
// 'TypeError'

// includes needs a string, not a regex
console.log('a1'.includes('1')); // true (string arg)
```

rx-apply-001.example:
```js
console.log('hello world foo'.match(/\w+/g)); // ['hello','world','foo']

// Messy spacing is handled cleanly
console.log('  a   b\tc '.match(/\w+/g)); // ['a','b','c']

// Guard against no matches
const words = '!!!'.match(/\w+/g) ?? [];
console.log(words); // []
```

rx-apply-mr-001.example:
```js
const s = 'a1 b2';
const re = /([a-z])(\d)/g;

// 1) matchAll (preferred)
for (const m of s.matchAll(re)) console.log(m[0], m[1], m[2]);
// a1 a 1 / b2 b 2

// 2) exec loop (equivalent, manages lastIndex itself)
const re2 = /([a-z])(\d)/g;
let m;
while ((m = re2.exec(s)) !== null) console.log(m[1] + '=' + m[2]);
// a=1 / b=2
```
